document.addEventListener('change',e=>{const d=e.target.dataset;if(e.target.id==='auto-roll'){game.options.autoRoll=e.target.checked;save();}if(d.member){selected=e.target.checked?[...new Set([...selected,d.member])]:selected.filter(id=>id!==d.member);}if(e.target.id==='weapon-mode'){fireType=e.target.value;render();}if(e.target.id==='fire-mode'){fireMode=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='reaction-position'){reactionT=Number(e.target.value)/1000;render();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);try{if(f.id==='morale-return'){const ids=d.getAll('card');E.activateOrder(game,actor(),d.get('order'),null,ids);save();dialog.close();render();}if(f.id==='setup'){const options=Object.fromEntries(d);options.autoRoll=d.has('autoRoll');options.specialCopies=Number(d.get('specialCopies'));options.armies=structuredClone(forceDrafts);if(d.get('battlefield')==='current'&&chosenMap)options.battlefield=structuredClone(chosenMap);game=E.newGame(options);selected=[];target=null;paused=false;tab='orders';snapshot={expanded};dialog.close();save();render();}if(f.id==='physical-dice'){acceptDice(Array.from({length:diceRequest.count},(_,i)=>Number(d.get('die-'+i))));}if(f.id==='force-form'){readForce();forceDrafts.forEach(armyTotals);localStorage.setItem('kdwarf-force-drafts',JSON.stringify(forceDrafts));setup();}if(f.id==='combat-plan'){const targets=Object.fromEntries(d);dialog.close();diceAction({type:'combat',targets},{orders:true});}if(f.id==='skill-plan'){const options={target:d.get('target')||null,program:d.get('program'),featureId:d.get('featureId')||null,extra:d.get('extra')||null,to:target&&{x:target.x,y:target.y}};dialog.close();if(d.get('reactive')==='true')diceAction({type:'reactive-action',kind:'skill',skill:d.get('kind'),id:d.get('id'),options});else diceAction({type:'skill',kind:d.get('kind'),id:d.get('id'),options},{orders:true});}}catch(e){toast(e.message);}});
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
q('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{game=Store.decode(await f.text());selected=[];target=null;paused=true;dialog.close();save();render();toast('Save loaded. AI paused.');}catch(e){toast(e.message);}e.target.value='';});
q('#army-import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{forceDrafts[forceSide]=decodeArmy(await f.text());forceForge();}catch(e){toast(e.message);}e.target.value='';});
